import re

_SETTING = re.compile(r"\s*([A-Za-z_]\w*)\s*=\s*(.*?)\s*$")


def split_ends(seq):
    if len(seq) < 2:
        raise ValueError("need at least two items")
    first, *middle, last = seq
    return first, middle, last


def read_chunks(read, size):
    chunks = []
    while (chunk := read(size)):
        chunks.append(chunk)
    return chunks


def parse_settings(lines):
    out = {}
    for line in lines:
        if (m := _SETTING.match(line)):
            out[m.group(1)] = m.group(2)
    return out

from dataclasses import dataclass


@dataclass(frozen=True)
class Num:
    value: object


@dataclass(frozen=True)
class Var:
    name: str


@dataclass(frozen=True)
class Add:
    left: object
    right: object


@dataclass(frozen=True)
class Mul:
    left: object
    right: object


def simplify(expr):
    match expr:
        case Num() | Var():
            return expr
        case Add(left, right):
            match simplify(left), simplify(right):
                case Num(a), Num(b):
                    return Num(a + b)
                case (Num(0), x) | (x, Num(0)):
                    return x
                case x, y if x == y:
                    return Mul(Num(2), x)
                case x, y:
                    return Add(x, y)
        case Mul(left, right):
            match simplify(left), simplify(right):
                case Num(a), Num(b):
                    return Num(a * b)
                case (Num(0), _) | (_, Num(0)):
                    return Num(0)
                case (Num(1), x) | (x, Num(1)):
                    return x
                case x, y:
                    return Mul(x, y)
    raise TypeError(f"not an expression: {expr!r}")


def evaluate(expr, env):
    match expr:
        case Num(value):
            return value
        case Var(name):
            return env[name]
        case Add(left, right):
            return evaluate(left, env) + evaluate(right, env)
        case Mul(left, right):
            return evaluate(left, env) * evaluate(right, env)
    raise TypeError(f"not an expression: {expr!r}")

