    if amount < 0 or n < 1:
        raise ValueError("need a non-negative total and n >= 1")
    cents = int(amount.quantize(_CENT, rounding=ROUND_HALF_UP).scaleb(2))
    base, extra = divmod(cents, n)
    return [Decimal(base + (1 if i < extra else 0)).scaleb(-2) for i in range(n)]


