from decimal import Decimal, ROUND_HALF_UP


class PercentOff:
    def __init__(self, percent):
        self.percent = Decimal(str(percent))

    def apply(self, price, order):
        return price - price * self.percent / 100


class FixedOff:
    def __init__(self, amount, code=None):
        self.amount = Decimal(str(amount))
        self.code = code

    def apply(self, price, order):
        if self.code is None or order.get("coupon") == self.code:
            return price - self.amount
        return price


class MinimumPrice:
    def __init__(self, floor):
        self.floor = Decimal(str(floor))

    def apply(self, price, order):
        return max(price, self.floor)


class PriceCalculator:
    def __init__(self, rules):
        self.rules = list(rules)

    def total(self, base_price, order=None):
        order = order or {}
        price = Decimal(str(base_price))
        for rule in self.rules:
            price = max(Decimal("0"), rule.apply(price, order))
        return price.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

class Rectangle:
    def __init__(self, width, height):
        if width <= 0 or height <= 0:
            raise ValueError("dimensions must be positive")
        self._w = width
        self._h = height

    @property
    def width(self):
        return self._w

    @property
    def height(self):
        return self._h

    @property
    def area(self):
        return self._w * self._h

    def with_width(self, w):
        return Rectangle(w, self._h)

    def with_height(self, h):
        return Rectangle(self._w, h)

    def __eq__(self, other):
        if not isinstance(other, Rectangle):
            return NotImplemented
        return (self._w, self._h) == (other._w, other._h)

    def __hash__(self):
        return hash((self._w, self._h))

    def __repr__(self):
        return f"{type(self).__name__}({self._w}, {self._h})"


class Square(Rectangle):
    def __init__(self, side):
        super().__init__(side, side)

    @property
    def side(self):
        return self._w

from typing import Protocol, runtime_checkable


@runtime_checkable
class Reader(Protocol):
    def read(self, n: int = -1) -> bytes:
        ...


@runtime_checkable
class Writer(Protocol):
    def write(self, data: bytes) -> int:
