class DuplicateUser(Exception):
    pass


class SignupService:
    def __init__(self, repo, mailer, clock):
        self.repo = repo
        self.mailer = mailer
        self.clock = clock
        self.failed_emails = []

    def signup(self, email):
        email = email.strip().lower()
        if "@" not in email:
            raise ValueError(f"invalid email {email!r}")
        if self.repo.get(email) is not None:
            raise DuplicateUser(email)
        user = {"email": email, "created_at": self.clock()}
        self.repo.add(user)
        try:
            self.mailer.send(email, "Welcome!")
        except Exception:
            self.failed_emails.append(email)
        return user

