_STRATEGIES = {}


def register_strategy(name):
    def deco(fn):
        _STRATEGIES[name] = fn
        return fn
    return deco


@register_strategy("by_name")
def _by_name(r):
    return r["name"].lower()


@register_strategy("by_age_desc")
def _by_age_desc(r):
    return (-r["age"], r["name"])


@register_strategy("by_created")
def _by_created(r):
    return r["created"]


def sort_records(records, strategy):
    if isinstance(strategy, str):
        try:
            key = _STRATEGIES[strategy]
        except KeyError:
            raise ValueError(f"unknown strategy {strategy!r}") from None
    elif hasattr(strategy, "key") and callable(strategy.key):
        key = strategy.key
    elif callable(strategy):
        key = strategy
    else:
        raise TypeError("strategy must be a name, a key function or an object with key()")
    return sorted(records, key=key)

class TextDocument:
    def __init__(self, text=""):
        self.text = text


class Insert:
    def __init__(self, pos, s):
        self.pos, self.s = pos, s

    def execute(self, doc):
        if not 0 <= self.pos <= len(doc.text):
            raise IndexError("position out of range")
        doc.text = doc.text[:self.pos] + self.s + doc.text[self.pos:]

    def undo(self, doc):
        doc.text = doc.text[:self.pos] + doc.text[self.pos + len(self.s):]


class Delete:
    def __init__(self, pos, length):
        self.pos, self.length = pos, length
        self.removed = None

    def execute(self, doc):
        if not 0 <= self.pos <= len(doc.text) or self.pos + self.length > len(doc.text):
            raise IndexError("range out of bounds")
        self.removed = doc.text[self.pos:self.pos + self.length]
        doc.text = doc.text[:self.pos] + doc.text[self.pos + self.length:]

    def undo(self, doc):
        doc.text = doc.text[:self.pos] + self.removed + doc.text[self.pos:]


class Editor:
    def __init__(self, doc):
        self.doc = doc
        self._undo = []
        self._redo = []

    def run(self, command):
        command.execute(self.doc)
        self._undo.append(command)
        self._redo.clear()

    def undo(self):
        if not self._undo:
            return False
        cmd = self._undo.pop()
        cmd.undo(self.doc)
        self._redo.append(cmd)
        return True

    def redo(self):
        if not self._redo:
            return False
        cmd = self._redo.pop()
        cmd.execute(self.doc)
        self._undo.append(cmd)
        return True

class Macro:
    def __init__(self, commands):
        self.commands = list(commands)

    def execute(self):
        done = []
        try:
            for cmd in self.commands:
                cmd.execute()
                done.append(cmd)
        except BaseException:
            for cmd in reversed(done):
                cmd.undo()
            raise

    def undo(self):
        for cmd in reversed(self.commands):
            cmd.undo()

