class LegacyLogHandler(logging.Handler):
    def __init__(self, legacy, level=logging.NOTSET):
        super().__init__(level)
        self.legacy = legacy

    @staticmethod
    def letter(levelno):
        i = bisect.bisect_right([lv for lv, _ in _LEVELS], levelno) - 1
