class InvalidTransition(Exception):
    def __init__(self, state, action):
        super().__init__(f"cannot {action} an order that is {state}")
        self.state = state
        self.action = action


_TRANSITIONS = {
    ("new", "pay"): "paid",
    ("paid", "ship"): "shipped",
    ("shipped", "deliver"): "delivered",
    ("new", "cancel"): "cancelled",
    ("paid", "cancel"): "cancelled",
}


class Order:
    def __init__(self):
        self._state = "new"
        self.history = []

    @property
    def state(self):
        return self._state

    def _do(self, action):
        nxt = _TRANSITIONS.get((self._state, action))
        if nxt is None:
            raise InvalidTransition(self._state, action)
        self.history.append((self._state, nxt))
        self._state = nxt

    def pay(self):
        self._do("pay")

    def ship(self):
        self._do("ship")

    def deliver(self):
        self._do("deliver")

    def cancel(self):
        self._do("cancel")

    def allowed_actions(self):
        return sorted(a for (s, a) in _TRANSITIONS if s == self._state)

