import re


def normalize(code):
    s = code.replace("-", "").replace(" ", "")
    if s.endswith("x"):
        s = s[:-1] + "X"
    return s


class ISBN:
    def __init__(self, code):
        if not ISBN.is_valid(code):
            raise ValueError(f"invalid ISBN-10: {code!r}")
        self.code = normalize(code)

    @staticmethod
    def is_valid(code):
        s = normalize(code)
        if not re.fullmatch(r"\d{9}[\dX]", s):
            return False
        total = sum((10 - i) * (10 if ch == "X" else int(ch)) for i, ch in enumerate(s))
        return total % 11 == 0

    @classmethod
    def parse(cls, code):
        return cls(code) if cls.is_valid(code) else None

    def __str__(self):
        return self.code

