        self.base = base
        self.keep_on_error = keep_on_error
        self.path = None

    def __enter__(self):
        self.path = Path(tempfile.mkdtemp(dir=self.base))
        return self.path

    def __exit__(self, exc_type, exc, tb):
        if exc_type is not None and self.keep_on_error:
            return False
        for dirpath, dirnames, _ in os.walk(self.path):
            for d in dirnames:
