import functools


def memoize(fn):
    cache = {}

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        try:
            return cache[key]
        except KeyError:
            pass
        result = fn(*args, **kwargs)
        cache[key] = result
        return result

    wrapper.cache = cache
    wrapper.clear = cache.clear
    return wrapper

