import cProfile
import io
import pstats


def _run(fn, args, kwargs):
    prof = cProfile.Profile()
    prof.enable()
    try:
        result = fn(*args, **kwargs)
    finally:
        prof.disable()
    return result, prof


def profile_call(fn, *args, **kwargs):
    result, prof = _run(fn, args, kwargs)
    counts = {}
    for (_, _, name), (cc, nc, *_rest) in pstats.Stats(prof).stats.items():
        total, prim = counts.get(name, (0, 0))
        counts[name] = (total + nc, prim + cc)
    return result, counts


def report(fn, *args, limit=5):
    _, prof = _run(fn, args, {})
    out = io.StringIO()
    pstats.Stats(prof, stream=out).sort_stats("cumulative").print_stats(limit)
    return out.getvalue()

