import threading

_STOP = object()


def run_pipeline(items, worker, n_workers=4):
    q = queue.Queue()
    results, errors = {}, {}
    lock = threading.Lock()

    def consume():
        while True:
            item = q.get()
            try:
                if item is _STOP:
                    return
                try:
                    r = worker(item)
                except Exception as exc:
                    with lock:
                        errors[item] = exc
                else:
                    with lock:
                        results[item] = r
            finally:
                q.task_done()

    threads = [threading.Thread(target=consume, daemon=True) for _ in range(n_workers)]
    for t in threads:
        t.start()
    for item in items:
        q.put(item)
    for _ in threads:
        q.put(_STOP)
    for t in threads:
        t.join()
    return results, errors

