            item = self._q.get()
            if item is _STOP:
                return
            try:
                self.handler(item)
            except Exception as exc:
                with self._lock:
                    self.errors.append(exc)
            finally:
                with self._lock:
                    self.processed += 1

    def submit(self, item):
        with self._lock:
            if self._closed:
                raise RuntimeError("pool is shut down")
            self._q.put(item)

    def shutdown(self, drain=True):
        with self._lock:
            self._closed = True
        discarded = 0
        if not drain:
            while True:
                try:
                    item = self._q.get_nowait()
                except queue.Empty:
                    break
                if item is not _STOP:
                    discarded += 1
        for _ in self._threads:
            self._q.put(_STOP)
        for t in self._threads:
            t.join()
        return discarded

