import re

UNITS: dict[str, int] = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_RE = re.compile(r"(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?")


def parse_duration(text: str) -> int:
    m = _RE.fullmatch(text)
    if not m or not any(m.groups()):
        raise ValueError(f"bad duration {text!r}")
    return sum(int(g) * UNITS[u] for g, u in zip(m.groups(), "dhms") if g is not None)


def format_duration(seconds: int, *, compact: bool = False) -> str:
    if seconds < 0:
        raise ValueError("negative duration")
    parts: list[str] = []
    for unit, size in UNITS.items():
        n, seconds = divmod(seconds, size)
        if n:
            parts.append(f"{n}{unit}")
    if not parts:
        return "0s"
    return ("" if compact else " ").join(parts)

