def _check(data, td, path):
    hints = typing.get_type_hints(td)
    for k in data:
        if k not in hints:
            raise ValueError(f"unknown key {path}{k}")
    for k in sorted(td.__required_keys__):
        if k not in data:
            raise ValueError(f"missing key {path}{k}")
    out = {}
    for k, v in data.items():
        t = hints[k]
        if typing.is_typeddict(t):
            if not isinstance(v, dict):
                raise ValueError(f"{path}{k} must be a dict")
            out[k] = _check(v, t, f"{path}{k}.")
        elif not isinstance(v, t) or (t is int and isinstance(v, bool)):
            raise ValueError(f"{path}{k} must be {t.__name__}")
        else:
            out[k] = v
    return out


def validate_user(data: object) -> UserRecord:
