        raise TypeError("user record must be a dict")
    return typing.cast(UserRecord, _check(data, UserRecord, ""))

import typing
from enum import IntEnum
from typing import Final, Literal

LogLevel = Literal["debug", "info", "warning", "error"]
DEFAULT_LEVEL: Final[LogLevel] = "info"


class Severity(IntEnum):
    DEBUG = 10
    INFO = 20
    WARNING = 30
    ERROR = 40


def parse_level(text: str) -> LogLevel:
    t = text.strip().lower()
    if t == "warn":
        t = "warning"
    allowed = typing.get_args(LogLevel)
    if t not in allowed:
        raise ValueError(f"unknown level {text!r}; expected one of {', '.join(allowed)}")
    return typing.cast(LogLevel, t)


def to_severity(level: LogLevel | Severity | int) -> Severity:
    if isinstance(level, Severity):
        return level
    if isinstance(level, bool):
        raise TypeError("bool is not a level")
    if isinstance(level, str):
        return Severity[parse_level(level).upper()]
    if isinstance(level, int):
        return Severity(level)
    raise TypeError(f"unsupported level {level!r}")


def at_least(level: LogLevel, threshold: LogLevel = DEFAULT_LEVEL) -> bool:
    return to_severity(level) >= to_severity(threshold)

