class Engine:
    instances = 0

    def __init__(self):
        Engine.instances += 1
        self.store = []
        self.disposed = False

    def connect(self):
        return Connection(self)

    def dispose(self):
        self.disposed = True


class Connection:
    def __init__(self, engine):
        self._engine = engine
        self._pending = []
        self.closed = False

    def _check(self):
        if self.closed:
            raise RuntimeError("connection is closed")

    def insert(self, row):
        self._check()
        self._pending.append(row)

    def rows(self):
        return list(self._engine.store) + list(self._pending)

    def commit(self):
        self._check()
        self._engine.store.extend(self._pending)
        self._pending = []

    def rollback(self):
        self._pending = []

    def close(self):
        self.closed = True


