RE = re.compile(r"(\d+):(\d+)")


def good(text):
    if not isinstance(text, str):
        raise TypeError("ratio must be a str")
    m = RE.fullmatch(text.strip())
    if not m:
        raise ValueError(f"bad ratio format: {text}")
    a, b = int(m.group(1)), int(m.group(2))
    if b == 0:
        raise ZeroDivisionError("zero denominator")
    return a, b


def zero_as_value_error(text):
    try:
        return good(text)
    except ZeroDivisionError:
        raise ValueError("zero denominator") from None


def none_on_bad(text):
    try:
        return good(text)
    except ValueError:
        return None


def other_message(text):
    try:
        return good(text)
    except ValueError:
        raise ValueError("invalid input") from None


def str_converts(text):
    return good(str(text))


def swapped(text):
    a, b = good(text)
    return b, a


def no_zero_check(text):
    if isinstance(text, str) and RE.fullmatch(text.strip()):
        a, b = text.strip().split(":")
        return int(a), int(b)
    return good(text)


def test_parse_ratio():
    assert parse_ratio("3:4") == (3, 4) and parse_ratio(" 16:9\n") == (16, 9)
    with pytest.raises(TypeError, match="ratio must be a str"):
        parse_ratio(None)
    with pytest.raises(ValueError, match="bad ratio format: 3:x"):
        parse_ratio("3:x")
    with pytest.raises(ZeroDivisionError, match="zero denominator"):
        parse_ratio("1:0")


def test_parse_ratio_rejects_signs_and_floats():
    for bad in ["-1:2", "1.5:2", "1:2:3", ":"]:
        with pytest.raises(ValueError):
            parse_ratio(bad)


