def rotate_logs(directory: Path, name: str, keep: int) -> list[str]:
    if keep < 1:
        raise ValueError("keep must be at least 1")
    directory = Path(directory)
    oldest = directory / f"{name}.{keep}"
    if oldest.exists():
        oldest.unlink()
    for i in range(keep - 1, 0, -1):
        src = directory / f"{name}.{i}"
        if src.exists():
            src.rename(directory / f"{name}.{i + 1}")
    base = directory / name
    if base.exists():
        base.rename(directory / f"{name}.1")
    base.touch()
