class RejectRow(Exception):
    def __init__(self, reason):
        super().__init__(reason)
        self.reason = reason


class PipelineError(Exception):
    def __init__(self, index, step, cause):
        super().__init__(f"row {index} failed in step {step!r}: {cause!r}")
        self.index = index
        self.step = step


class Pipeline:
    def __init__(self, steps):
        self.steps = list(steps)

    def run(self, rows):
        outputs, rejects = [], []
        for i, original in enumerate(rows):
            row = dict(original)
            for name, fn in self.steps:
                try:
                    row = fn(row)
                except RejectRow as r:
                    rejects.append({"index": i, "step": name, "reason": r.reason, "row": original})
                    break
                except Exception as exc:
                    raise PipelineError(i, name, exc) from exc
            else:
                outputs.append(row)
        return outputs, rejects

import time

_NEG = object()


class ReadThroughCache:
    def __init__(self, loader, ttl: float, clock=time.monotonic, negative_ttl=None):
        self.loader = loader
        self.ttl = ttl
        self.clock = clock
        self.negative_ttl = negative_ttl
        self._data = {}
        self.stats = {"hits": 0, "misses": 0, "loads": 0}

    def get(self, key):
        now = self.clock()
        entry = self._data.get(key)
        if entry is not None and now < entry[1]:
            self.stats["hits"] += 1
            if entry[0] is _NEG:
                raise KeyError(key)
            return entry[0]
        self.stats["misses"] += 1
        self.stats["loads"] += 1
        try:
            value = self.loader(key)
        except KeyError:
            if self.negative_ttl is not None:
                self._data[key] = (_NEG, now + self.negative_ttl)
            else:
                self._data.pop(key, None)
            raise
        self._data[key] = (value, now + self.ttl)
        return value

    def invalidate(self, key):
        self._data.pop(key, None)

import threading


class _Call:
    def __init__(self):
        self.done = threading.Event()
        self.result = None
        self.error = None
        self.callers = 1


class SingleFlight:
    def __init__(self):
        self._lock = threading.Lock()
        self._calls = {}

    def inflight(self, key):
        with self._lock:
            c = self._calls.get(key)
            return c.callers if c else 0

    def do(self, key, fn):
        with self._lock:
            call = self._calls.get(key)
            if call is not None:
                call.callers += 1
                leader = False
            else:
                call = self._calls[key] = _Call()
                leader = True
        if leader:
            try:
                call.result = fn()
            except BaseException as exc:
                call.error = exc
            finally:
                with self._lock:
                    del self._calls[key]
                call.done.set()
        else:
            call.done.wait()
        if call.error is not None:
            raise call.error
        return call.result

import hashlib
import json
import time


class IdempotencyConflict(Exception):
    pass


def _fingerprint(payload):
    return hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()


class IdempotencyStore:
    def __init__(self, ttl: float = 86400, clock=time.monotonic):
        self.ttl = ttl
        self.clock = clock
        self._entries = {}

    def _get(self, key):
        e = self._entries.get(key)
        if e is not None and self.clock() >= e[2]:
            del self._entries[key]
            return None
        return e

    def handle(self, key, payload, fn):
        fp = _fingerprint(payload)
        e = self._get(key)
        if e is not None:
            if e[0] != fp:
                raise IdempotencyConflict(f"key {key!r} reused with a different payload")
            return e[1]
        response = fn(payload)
        self._entries[key] = (fp, response, self.clock() + self.ttl)
        return response

    def __len__(self):
        now = self.clock()
        return sum(1 for e in self._entries.values() if now < e[2])

import threading


class RequestInProgress(Exception):
    pass


_RUNNING = object()


class IdempotentHandler:
    def __init__(self, fn):
        self.fn = fn
        self._lock = threading.Lock()
        self._state = {}

    def call(self, key, payload):
        with self._lock:
            st = self._state.get(key)
            if st is _RUNNING:
                raise RequestInProgress(key)
            if st is not None:
                return st[0]
            self._state[key] = _RUNNING
        try:
            result = self.fn(payload)
        except BaseException:
            with self._lock:
                del self._state[key]
            raise
        with self._lock:
            self._state[key] = (result,)
        return result

