import dataclasses
import datetime
import decimal
import json


class ExtendedEncoder(json.JSONEncoder):
    def default(self, o):
        if isinstance(o, datetime.datetime):
            return {"__type__": "datetime", "value": o.isoformat()}
        if isinstance(o, datetime.date):
            return {"__type__": "date", "value": o.isoformat()}
        if isinstance(o, decimal.Decimal):
            return {"__type__": "decimal", "value": str(o)}
        if isinstance(o, (set, frozenset)):
            return {"__type__": "set", "value": sorted(o)}
        if dataclasses.is_dataclass(o) and not isinstance(o, type):
            return {f.name: getattr(o, f.name) for f in dataclasses.fields(o)}
        return super().default(o)


_DECODERS = {
    "datetime": datetime.datetime.fromisoformat,
    "date": datetime.date.fromisoformat,
    "decimal": decimal.Decimal,
    "set": set,
}


def decode_hook(obj):
    if set(obj) == {"__type__", "value"} and obj["__type__"] in _DECODERS:
        return _DECODERS[obj["__type__"]](obj["value"])
    return obj


def dumps(obj, **kwargs):
    return json.dumps(obj, cls=ExtendedEncoder, **kwargs)


def loads(text):
    return json.loads(text, object_hook=decode_hook)

from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo


def to_zone(timestamp, zone):
    dt = datetime.fromisoformat(timestamp)
    if dt.tzinfo is None:
        raise ValueError("timestamp has no UTC offset")
    return dt.astimezone(ZoneInfo(zone)).isoformat()


def daily_series(start_local, zone, count):
    tz = ZoneInfo(zone)
    start = datetime.fromisoformat(start_local)
    if start.tzinfo is not None:
        raise ValueError("expected a naive local time")
    return [(start + timedelta(days=i)).replace(tzinfo=tz).astimezone(timezone.utc).isoformat()
            for i in range(count)]

