import subprocess
import sys


class CommandFailed(Exception):
    def __init__(self, returncode, stderr):
        super().__init__(f"exit status {returncode}: {stderr.strip()}")
        self.returncode = returncode
        self.stderr = stderr


def run_python(code, *, args=(), stdin_text="", timeout=5.0):
    try:
        p = subprocess.run([sys.executable, "-c", code, *args], input=stdin_text, capture_output=True,
                           text=True, timeout=timeout)
    except subprocess.TimeoutExpired as exc:
        raise TimeoutError(f"timed out after {timeout}s") from exc
    return p.returncode, p.stdout, p.stderr


def check_python(code, **kwargs):
    rc, out, err = run_python(code, **kwargs)
    if rc != 0:
        raise CommandFailed(rc, err)
    return out

