        writer.writeheader()
        writer.writerows(records)
    return header


def detect_delimiter(path):
    with open(path, newline="", encoding="utf-8") as f:
        sample = f.read(4096)
    try:
        return csv.Sniffer().sniff(sample, delimiters=",;\t|").delimiter
    except csv.Error as exc:
        raise ValueError(f"cannot detect delimiter of {path}") from exc


def convert(src, dst, dialect):
    delim = detect_delimiter(src)
    with open(src, newline="", encoding="utf-8") as f:
        rows = list(csv.DictReader(f, delimiter=delim))
    write_records(dst, rows, dialect=dialect)
    return len(rows)

def first_bad(n, is_bad):
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if is_bad(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo


def floor_root(n, k):
    if n < 0 or k < 1:
        raise ValueError("need n >= 0 and k >= 1")
    lo, hi = 0, 1 << (n.bit_length() // k + 1)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid ** k <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def longest_within_budget(sizes, budget):
    best_start, best_len = 0, 0
    start = total = 0
    for end, s in enumerate(sizes):
        total += s
        while total > budget and start <= end:
            total -= sizes[start]
            start += 1
        if end - start + 1 > best_len:
            best_start, best_len = start, end - start + 1
    return best_start, best_len


def _at_most(a, b, limit):
    j, count = len(b) - 1, 0
    for x in a:
        while j >= 0 and x + b[j] > limit:
            j -= 1
        count += j + 1
    return count


def count_pairs_between(a, b, lo, hi):
    if lo > hi:
        return 0
    return _at_most(a, b, hi) - _at_most(a, b, lo - 1)

import re

_RUNS = re.compile(r"(\d+)")


def natural_key(s):
    key = []
    for i, part in enumerate(_RUNS.split(s)):
        if not part:
            continue
        key.append((0, int(part), "") if i % 2 else (1, 0, part.lower()))
    return tuple(key)


def sort_by_spec(rows, spec):
    out = list(rows)
    for field, order in reversed(spec):
        if order not in ("asc", "desc"):
            raise ValueError(f"bad order {order!r}")
        out.sort(key=lambda r: r[field], reverse=order == "desc")
    return out

