from math import factorial


def distinct_permutations(items):
    a = sorted(items)
    while True:
        yield tuple(a)
        i = len(a) - 2
        while i >= 0 and a[i] >= a[i + 1]:
            i -= 1
        if i < 0:
            return
        j = len(a) - 1
        while a[j] <= a[i]:
            j -= 1
        a[i], a[j] = a[j], a[i]
        a[i + 1:] = reversed(a[i + 1:])


def _multinomial(counts):
    total = factorial(sum(counts.values()))
    for c in counts.values():
        total //= factorial(c)
    return total


def count_distinct_permutations(items):
    return _multinomial(Counter(items))


def nth_permutation(items, k):
    pool = Counter(items)
    if not 0 <= k < _multinomial(pool):
        raise IndexError("k out of range")
    out = []
    for _ in range(len(items)):
        for x in sorted(pool):
            if pool[x] == 0:
                continue
            pool[x] -= 1
            c = _multinomial(pool)
            if k < c:
                out.append(x)
                break
            k -= c
            pool[x] += 1
    return tuple(out)

def best_lineup(talks, minutes):
    if minutes < 0 or any(d <= 0 for d, _ in talks):
        raise ValueError("minutes must be >= 0 and durations positive")
    best = [0] * (minutes + 1)
    took = []
    for duration, score in talks:
        row = bytearray(minutes + 1)
        for t in range(minutes, duration - 1, -1):
            cand = best[t - duration] + score
            if cand > best[t]:
                best[t] = cand
                row[t] = 1
        took.append(row)
    chosen, t = [], minutes
    for i in range(len(talks) - 1, -1, -1):
        if took[i][t]:
            chosen.append(i)
            t -= talks[i][0]
    return best[minutes], sorted(chosen)

import heapq


def best_route(roads, start, goal):
    graph = {}
    for a, b, cost in roads:
        if cost < 0:
            raise ValueError(f"negative cost on {a} -> {b}")
        graph.setdefault(a, []).append((b, cost))
    heap = [(0, 0, (start,))]
    settled = set()
    while heap:
        cost, hops, path = heapq.heappop(heap)
        node = path[-1]
        if node in settled:
            continue
        settled.add(node)
        if node == goal:
            return cost, list(path)
        for nxt, w in graph.get(node, ()):
            if nxt not in settled:
                heapq.heappush(heap, (cost + w, hops + 1, path + (nxt,)))
    return None

def connection_times(n, cables, queries):
    parent = list(range(n))
    size = [1] * n
    stamp = [-1] * n

    def root(x):
        while parent[x] != x:
            x = parent[x]
        return x

    for i, (a, b) in enumerate(cables):
        ra, rb = root(a), root(b)
        if ra == rb:
            continue
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        stamp[rb] = i

    def chain(x):
        out = [x]
        while parent[x] != x:
            x = parent[x]
            out.append(x)
        return out

    answers = []
    for a, b in queries:
        if a == b:
            answers.append(-1)
            continue
        pa, pb = chain(a), chain(b)
        if pa[-1] != pb[-1]:
            answers.append(None)
            continue
        on_b = set(pb)
        best = -1
        for x in pa:
            if x in on_b:
                lca = x
                break
            best = max(best, stamp[x])
        for x in pb:
            if x == lca:
                break
            best = max(best, stamp[x])
        answers.append(best)
    return answers

