def longest(tasks):
    memo = {}
    for _ in range(len(tasks)):
        for n in tasks:
            d, deps = tasks[n]
            if all(x in memo for x in deps):
                memo[n] = d + max((memo[x] for x in deps), default=0)
    return max(memo.values(), default=0)


